from collections import deque
g = {0: [1, 3], 1: [0, 2], 2: [1, 3], 3: [2, 0]}
colour = {0: 0}
q = deque([0]); ok = True
while q:
    u = q.popleft()
    for v in g[u]:
        if v not in colour:
            colour[v] = 1 - colour[u]; q.append(v)
        elif colour[v] == colour[u]: ok = False
print(ok, len(colour))

from collections import deque
g = {0: [1, 2], 1: [0, 3], 2: [0, 3], 3: [1, 2, 4], 4: [3]}
seen = {0}
q = deque([0])
order = []
while q:
    u = q.popleft(); order.append(u)
    for v in g[u]:
        if v not in seen:
            seen.add(v); q.append(v)
print(order)

g = {0: [1], 1: [0], 2: [3], 3: [2]}
seen = set()
def dfs(u):
    seen.add(u)
    for v in g[u]:
        if v not in seen: dfs(v)
comp = 0
for s in g:
    if s not in seen: comp += 1; dfs(s)
print(comp, sorted(seen))

from collections import deque
g = {0: [1, 2], 1: [3], 2: [3], 3: []}
level = {0: 0}
q = deque([0]); last = 0
while q:
    u = q.popleft(); last = level[u]
    for v in g[u]:
        if v not in level:
            level[v] = level[u] + 1; q.append(v)
print(last, level[3])
